namespace APIArena.Domain.Scenarios;

/// <summary>
/// duplicate-webhook-v1: one synthetic payment event delivered <see cref="Copies"/> times with distinct delivery ids.
/// Event and aggregate ids are generated by the server per run (never taken from the template or the user).
/// </summary>
public sealed record DuplicateWebhookDefinition(string EventType, long Amount, string Currency, int Copies, bool Parallel);

/// <summary>out-of-order-webhook-v1: version 2 is sent first, version 1 (stale) afterwards, spaced by <see cref="GapMs"/>.</summary>
public sealed record OutOfOrderWebhookDefinition(string EventType, int LatestVersion, string LatestStatus, int StaleVersion, string StaleStatus,
    long Amount, string Currency, int GapMs);
